/**
 * singbox-tools-interface
 * Singbox-Tools 一键SSH命令生成器 - Cloudflare Workers 单文件版
 * 项目脚本来源: https://github.com/jyucoeng/singbox-tools
 * 其他命令查询: https://pkg.tbbbk.com/
 *
 * 部署方式一(控制台): CF Dashboard -> Workers & Pages -> Create Worker -> 粘贴本文件全部内容 -> Deploy
 * 部署方式二(Wrangler): 本目录下执行 `wrangler deploy` (配置见 wrangler.toml)
 * 部署方式三(GitHub): 推送到 GitHub 后手动运行 "Deploy to Cloudflare Workers" 工作流
 *                     （需配置 CLOUDFLARE_API_TOKEN / CLOUDFLARE_ACCOUNT_ID 两个 Secrets）
 *
 * 本文件由 build.py 从 index.html 自动生成，请勿直接修改；改界面请编辑 index.html 后重新运行 build.py。
 */

const HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>Singbox-Tools 一键SSH命令生成器</title>\n  <style>\n    :root {\n      --bg:#0b1020;\n      --card:#121831;\n      --ink:#e9edf7;\n      --sub:#b7c1d9;\n      --line:#263255;\n      --acc:#4f7cff;\n      --acc-soft:rgba(79,124,255,.14);\n      --ok:#22c55e;\n      --warn:#f59e0b;\n      --err:#ef4444;\n      --input-bg:#0d1430;\n      --button-bg-dark:#1a2346;\n      --button-bg-light:#121a39;\n      --body-bg: linear-gradient(180deg, var(--bg) 0%, #0e1530 100%);\n    }\n    body.light-mode {\n      --bg:#f4f7fc;\n      --card:#ffffff;\n      --ink:#1a202c;\n      --sub:#4a5568;\n      --line:#dbe2ef;\n      --acc:#3b6cf6;\n      --acc-soft:rgba(59,108,246,.10);\n      --ok:#16a34a;\n      --warn:#d97706;\n      --err:#dc2626;\n      --input-bg:#ffffff;\n      --button-bg-dark:#e2e8f0;\n      --button-bg-light:#f0f4f9;\n      --body-bg: var(--bg);\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      background: var(--body-bg);\n      color: var(--ink);\n      font: 16px/1.5 system-ui, -apple-system, \"Segoe UI\", Roboto, Ubuntu, \"Helvetica Neue\", Arial, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n      transition: background-color .3s, color .3s;\n    }\n    .wrap { max-width: 1450px; margin: 28px auto 40px; padding: 0 20px; }\n    a { color: var(--acc); text-decoration: none; }\n    a:hover { text-decoration: underline; }\n\n    /* ---------- header ---------- */\n    header { position: relative; margin-bottom: 18px; display: flex; justify-content: center; align-items: center; flex-direction: column; }\n    header h1 { font-size: 34px; margin: 0 0 8px; text-align: center; }\n    header p { margin: 0; font-size: 14px; color: var(--sub); line-height: 1.7; text-align: center; }\n    .theme-btn {\n      position: absolute; top: 0; right: 0;\n      width: 42px; height: 42px; border-radius: 50%;\n      border: 1px solid var(--line); background: var(--card);\n      font-size: 20px; cursor: pointer; line-height: 1;\n      transition: transform .2s;\n    }\n    .theme-btn:hover { transform: rotate(20deg); }\n\n    /* ---------- tabs ---------- */\n    .tabs { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 20px; }\n    .tab {\n      padding: 10px 18px; border-radius: 12px; cursor: pointer;\n      border: 1px solid var(--line); background: var(--card); color: var(--sub);\n      font-size: 15px; font-weight: 600; transition: all .2s;\n    }\n    .tab:hover { color: var(--ink); border-color: var(--acc); }\n    .tab.active { background: var(--acc); border-color: var(--acc); color: #fff; }\n    .tabpane { display: none; }\n    .tabpane.active { display: block; animation: fadeUp .25s ease; }\n    /* 板块出现动画：从 display:none 恢复显示时自动重放 */\n    @keyframes fadeUp {\n      from { opacity: 0; transform: translateY(8px); }\n      to { opacity: 1; transform: none; }\n    }\n    #mg-card, #mtpn-telemt-card { animation: fadeUp .25s ease; }\n\n    /* ---------- grid & cards ---------- */\n    .grid { display: grid; grid-template-columns: 1.05fr 1fr; gap: 20px; }\n    .grid + .grid { margin-top: 20px; }\n    @media (max-width: 1100px) {\n      .grid { grid-template-columns: 1fr; }\n    }\n    .card {\n      background: rgba(127,157,255,.055);\n      backdrop-filter: blur(6px);\n      border: 1px solid var(--line);\n      border-radius: 16px;\n      padding: 20px;\n      transition: background-color .3s, border-color .3s;\n    }\n    body.light-mode .card { background: var(--card); box-shadow: 0 1px 3px rgba(15,23,42,.06); }\n    .card h2 { margin: 0 0 6px; font-size: 19px; }\n    .card h2 .card-num { font-weight: 700; margin-right: 4px; }\n    .card h3 { margin: 16px 0 8px; font-size: 15px; color: var(--acc); }\n    .card h3:first-of-type { margin-top: 10px; }\n    .col { display: flex; flex-direction: column; gap: 20px; min-width: 0; }\n    .col > .card:last-child { flex: 1 0 auto; }\n    .span2 { grid-column: 1 / -1; }\n    .tip { font-size: 12.5px; font-weight: 400; color: var(--sub); margin-left: 6px; }\n    .note { font-size: 12.5px; color: var(--sub); margin: 8px 0 0; line-height: 1.6; }\n    .note b { color: var(--warn); }\n\n    /* ---------- rows & inputs ---------- */\n    .row { display: grid; grid-template-columns: 205px 1fr; gap: 10px; align-items: center; margin: 10px 0; }\n    @media (max-width: 700px) { .row { grid-template-columns: 1fr; } }\n    .row > label { font-size: 14.5px; text-align: left; }\n    @media (max-width: 700px) { .row > label { text-align: left; } }\n    .ctl { display: flex; gap: 8px; }\n    .ctl > input, .ctl > select, .ctl > textarea { flex: 1; min-width: 0; }\n    .ctl > button { flex: 0 0 auto; }\n    .ctl > select.sni-pick { flex: 0 0 auto; width: auto; max-width: 230px; }\n    input[type=\"text\"], select, textarea {\n      width: 100%;\n      background: var(--input-bg);\n      border: 1px solid var(--line);\n      color: var(--ink);\n      border-radius: 10px;\n      padding: 9px 12px;\n      font: 14px/1.4 ui-monospace, SFMono-Regular, Consolas, \"Courier New\", monospace;\n      outline: none;\n      transition: border-color .2s;\n    }\n    input[type=\"text\"]:focus, select:focus, textarea:focus { border-color: var(--acc); }\n    #mg-out { min-height: 120px; resize: vertical; line-height: 1.5; }\n    input.err { border-color: var(--err); box-shadow: 0 0 0 1px var(--err); }\n    fieldset.lock-box { border: 0; margin: 0; padding: 0; min-width: 0; transition: opacity .25s; }\n    .card.locked .lock-box { opacity: .6; }\n    input::placeholder { color: var(--sub); opacity: .65; }\n    input:disabled { opacity: .4; cursor: not-allowed; }\n    select { font-family: inherit; cursor: pointer; }\n    .pill {\n      display: inline-block; font-size: 11px; padding: 1px 7px; margin-left: 4px;\n      border-radius: 6px; border: 1px solid var(--line);\n      background: var(--acc-soft); color: var(--acc);\n      font-family: ui-monospace, Consolas, monospace; vertical-align: 1px;\n    }\n    .req { color: var(--err); font-weight: 700; margin-left: 4px; }\n    .warn-org { color: var(--warn); font-weight: 600; }\n    .err-banner {\n      max-width: 1450px; margin: 0 auto 16px; padding: 10px 14px;\n      border: 1px solid var(--err); border-radius: 12px;\n      background: rgba(239,68,68,.08); color: var(--err);\n      font-size: 13.5px; line-height: 1.6;\n    }\n\n    /* protocol grid */\n    .pgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 14px; }\n    @media (max-width: 700px) { .pgrid { grid-template-columns: 1fr; } }\n    .pitem label { display: block; font-size: 14px; margin-bottom: 4px; }\n    .sep { border-top: 1px dashed var(--line); margin: 14px 0 4px; }\n\n    /* ---------- buttons ---------- */\n    button.primary, button.mini, button.ghost {\n      cursor: pointer; border-radius: 10px; font-size: 14px;\n      border: 1px solid var(--line); transition: all .2s;\n      font-family: inherit;\n    }\n    button.primary { background: var(--acc); color: #fff; border-color: var(--acc); padding: 9px 18px; font-weight: 600; }\n    button.primary:hover { filter: brightness(1.12); }\n    button.mini { background: var(--button-bg-dark); color: var(--ink); padding: 7px 12px; }\n    button.mini:hover { border-color: var(--acc); color: var(--acc); }\n    button.ghost { background: transparent; color: var(--sub); padding: 9px 18px; }\n    button.ghost:hover { color: var(--ink); border-color: var(--acc); }\n    button:disabled { opacity: .45; cursor: not-allowed; }\n\n    /* ---------- command list (速查) ---------- */\n    .cmdlist { display: grid; grid-template-columns: 1fr 1fr; gap: 0 26px; }\n    @media (max-width: 900px) { .cmdlist { grid-template-columns: 1fr; } }\n    .crow {\n      display: flex; align-items: center; gap: 8px;\n      padding: 6px 4px;\n      border-bottom: 1px dashed var(--line);\n    }\n    .crow code {\n      font-family: ui-monospace, Consolas, monospace; font-size: 12.5px;\n      color: var(--ok); word-break: break-all; flex: 1;\n    }\n    .crow .cdesc { flex: 0 0 auto; max-width: 46%; font-size: 12.5px; color: var(--sub); }\n    .crow button { flex: 0 0 auto; font-size: 12px; padding: 4px 10px; border-radius: 8px; }\n    .crow.hl {\n      padding: 8px 10px;\n      margin: 4px 0;\n      border: 1px solid var(--acc);\n      border-radius: 10px;\n      background: var(--acc-soft);\n      box-shadow: 0 0 0 1px var(--acc-soft), 0 0 14px rgba(79,124,255,.45);\n      animation: hlPulse 2.4s ease-in-out infinite;\n    }\n    @keyframes hlPulse {\n      0%, 100% { box-shadow: 0 0 0 1px var(--acc-soft), 0 0 6px rgba(79,124,255,.35); }\n      50% { box-shadow: 0 0 0 1px var(--acc-soft), 0 0 18px rgba(79,124,255,.6); }\n    }\n\n    /* ---------- output ---------- */\n    .out-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin: 10px 0; }\n    .out-tools label { font-size: 14px; color: var(--sub); display: flex; align-items: center; gap: 6px; }\n    .out-tools select { width: auto; padding: 7px 10px; }\n    #cmd {\n      min-height: 150px; resize: vertical; white-space: pre;\n      font-size: 13.5px; line-height: 1.55;\n    }\n    .hint { font-size: 12.5px; color: var(--sub); margin: 8px 0 0; }\n\n    footer { margin-top: 26px; text-align: center; font-size: 13px; color: var(--sub); line-height: 1.8; }\n    .ok-msg { color: var(--ok) !important; }\n  </style>\n</head>\n<body>\n<div class=\"wrap\">\n\n  <header>\n    <button id=\"theme-btn\" class=\"theme-btn\" title=\"切换深色/浅色模式\">☀️</button>\n    <h1>Singbox-Tools 脚本工具箱🧰 一键SSH命令生成器</h1>\n    <p>\n      项目地址：<a href=\"https://github.com/jyucoeng/singbox-tools\" target=\"_blank\">github.com/jyucoeng/singbox-tools</a>\n      　|　其他命令查询：<a href=\"https://pkg.tbbbk.com/\" target=\"_blank\">pkg.tbbbk.com（Linux 应用安装器 · 180+ 应用一键安装命令）</a>\n    </p>\n  </header>\n\n  <nav class=\"tabs\">\n    <button class=\"tab active\" data-tab=\"sb\">📦 Singbox 一键脚本</button>\n    <button class=\"tab\" data-tab=\"mtpnew\">✈️ MTProxy 新版</button>\n  </nav>\n\n  <div class=\"err-banner\" id=\"err-global\" style=\"display:none\"></div>\n\n  <!-- ================= Tab 1 : sb.sh ================= -->\n  <section id=\"tab-sb\" class=\"tabpane active\">\n    <div class=\"grid\">\n      <div class=\"col\">\n      <section class=\"card\">\n        <h2>① 协议与端口 <span class=\"tip\">填写端口即启用该协议，留空则不启用</span></h2>\n\n        <h3>直连协议（可自由组合）</h3>\n        <div class=\"pgrid\">\n          <div class=\"pitem\"><label>Hysteria2 <span class=\"pill\">hypt</span></label><input type=\"text\" class=\"port-input\" id=\"hypt\" placeholder=\"如 2082，或点 🎲 随机\" inputmode=\"numeric\"></div>\n          <div class=\"pitem\"><label>Vless-Reality <span class=\"pill\">vlrt</span></label><input type=\"text\" class=\"port-input\" id=\"vlrt\" placeholder=\"如 2083，或点 🎲 随机\" inputmode=\"numeric\"></div>\n          <div class=\"pitem\"><label>Tuic <span class=\"pill\">tupt</span></label><input type=\"text\" class=\"port-input\" id=\"tupt\" placeholder=\"如 2082，或点 🎲 随机\" inputmode=\"numeric\"></div>\n          <div class=\"pitem\"><label>AnyTLS <span class=\"pill\">anypt</span></label><input type=\"text\" class=\"port-input\" id=\"anypt\" placeholder=\"如 2082，或点 🎲 随机\" inputmode=\"numeric\"></div>\n        </div>\n\n        <div class=\"sep\"></div>\n        <h3>Argo CDN 协议（三选一：VMess-WS-TLS / Trojan-WS-TLS / Vless-WS-TLS）</h3>\n        <div class=\"row\">\n          <label>Argo 协议选择 <span class=\"pill\">argo</span></label>\n          <select id=\"argo\">\n            <option value=\"\">不启用 Argo</option>\n            <option value=\"vmpt\">VMess-WS-TLS + Argo（vmpt）</option>\n            <option value=\"trpt\">Trojan-WS-TLS + Argo（trpt）</option>\n            <option value=\"vlpt\">Vless-WS-TLS + Argo（vlpt）</option>\n          </select>\n        </div>\n        <div class=\"row\" id=\"row-argo-port\" style=\"display:none\">\n          <label>Argo 协议本地端口 <span class=\"pill\" id=\"argo-port-pill\">vmpt</span></label>\n          <input type=\"text\" class=\"port-input\" id=\"argo-port\" placeholder=\"如 41003，或点 🎲 随机\" inputmode=\"numeric\" disabled>\n        </div>\n\n        <div class=\"sep\"></div>\n        <h3>直连协议 SNI <span class=\"tip\">填写对应端口后显示</span></h3>\n        <div class=\"row\" id=\"row-hy-sni\" style=\"display:none\">\n          <label>Hysteria2 SNI <span class=\"pill\">hy_sni</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"hy_sni\" placeholder=\"留空默认 www.apple.com，或右侧选择\">\n            <select class=\"sni-pick\" data-target=\"hy_sni\"><option value=\"\">选择…</option></select>\n          </div>\n        </div>\n        <div class=\"row\" id=\"row-vl-sni\" style=\"display:none\">\n          <label>Vless SNI <span class=\"pill\">vl_sni</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"vl_sni\" placeholder=\"留空默认 www.apple.com（Vless-Reality）\">\n            <select class=\"sni-pick\" data-target=\"vl_sni\"><option value=\"\">选择…</option></select>\n          </div>\n        </div>\n        <div class=\"row\" id=\"row-tu-sni\" style=\"display:none\">\n          <label>Tuic SNI <span class=\"pill\">tu_sni</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"tu_sni\" placeholder=\"留空默认 www.apple.com，或右侧选择\">\n            <select class=\"sni-pick\" data-target=\"tu_sni\"><option value=\"\">选择…</option></select>\n          </div>\n        </div>\n        <div class=\"row\" id=\"row-any-sni\" style=\"display:none\">\n          <label>AnyTLS SNI <span class=\"pill\">any_sni</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"any_sni\" placeholder=\"留空默认 www.apple.com，或右侧选择\">\n            <select class=\"sni-pick\" data-target=\"any_sni\"><option value=\"\">选择…</option></select>\n          </div>\n        </div>\n        <p class=\"note\"><b>SNI 安全提示：</b>不要使用 Cloudflare/Akamai 等代理或 CDN 域名作为 SNI，否则端口被扫描后会沦为无限制流量转发端口。不确定就留空（内置默认值）。</p>\n\n        <p class=\"note\">协议组合与节点数量对照表见 <a href=\"https://github.com/jyucoeng/singbox-tools/blob/main/README-sb.md\" target=\"_blank\">README-sb.md</a>；Argo 固定隧道需自备 CF Tunnel。</p>\n      </section>\n\n      <section class=\"card\" id=\"argo-tunnel-card\">\n        <h2>③ Argo 隧道</h2>\n        <div class=\"row\">\n          <label>隧道类型</label>\n          <select id=\"tunnel-type\">\n            <option value=\"tmp\">临时隧道（Cloudflare 自动分配随机域名）</option>\n            <option value=\"fixed\" selected>固定隧道（自有域名 / CF Tunnel）</option>\n          </select>\n        </div>\n        <div class=\"row\" id=\"row-agn\">\n          <label>Argo 固定隧道域名 <span class=\"pill\">agn</span></label>\n          <input type=\"text\" id=\"agn\" placeholder=\"如 yy.example.com 或 xx.trycloudflare.com\">\n        </div>\n        <div class=\"row\" id=\"row-agk\">\n          <label>Argo 隧道 Token <span class=\"pill\">agk</span></label>\n          <input type=\"text\" id=\"agk\" placeholder=\"ey 开头字符串或 {…} JSON，引号自动处理\">\n        </div>\n        <p class=\"note\" id=\"tunnel-note\">固定隧道：请填写上方「Argo 固定隧道域名」与「Argo 隧道 Token」；自有 CF Tunnel 可在 <a href=\"https://fscarmen.cloudflare.now.cc\" target=\"_blank\">fscarmen CF Json 生成网</a> 获取 JSON Token（仅选了 Argo 协议才需要）。</p>\n        <div class=\"sep\"></div>\n        <div class=\"row\">\n          <label>CF 优选域名 <span class=\"pill\">cdn_host</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"cdn_host\" placeholder=\"留空默认 saas.sin.fan，或右侧选择\">\n            <select class=\"pick-cdn\" data-target=\"cdn_host\"><option value=\"\">选择…</option></select>\n          </div>\n        </div>\n        <div class=\"row\">\n          <label>CF 对外端口 <span class=\"pill\">cdn_pt</span></label>\n          <select id=\"cdn_pt\">\n            <option value=\"\">默认 443</option>\n            <option value=\"2053\">2053</option>\n            <option value=\"2083\">2083</option>\n            <option value=\"2087\">2087</option>\n            <option value=\"2096\">2096</option>\n            <option value=\"8443\">8443</option>\n          </select>\n        </div>\n        <div class=\"row\">\n          <label>Argo 本地监听端口 <span class=\"pill\">argo_pt</span></label>\n          <input type=\"text\" id=\"argo_pt\" placeholder=\"默认 8001，一般不建议修改\" inputmode=\"numeric\">\n        </div>\n        <p class=\"note warn-org\">⚠️ 该端口为 Cloudflare 中配置的 HTTP 对应的映射端口。</p>\n        </section>\n      </div>\n\n      <div class=\"col\">\n      <section class=\"card\">\n        <h2>② 全局配置</h2>\n        <div class=\"row\">\n          <label>UUID 密码 <span class=\"pill\">uuid</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"uuid\" placeholder=\"留空则自动生成 UUID\">\n            <button type=\"button\" class=\"mini\" id=\"gen-uuid\">生成</button>\n          </div>\n        </div>\n        <div class=\"row\">\n          <label>节点名称前缀 <span class=\"pill\">name</span></label>\n          <input type=\"text\" id=\"name\" placeholder=\"如 HK，生成 HK-vmess / HK-vless 等\">\n        </div>\n        <div class=\"row\">\n          <label>IPv4/IPv6 导出 <span class=\"pill\">ippz</span></label>\n          <select id=\"ippz\">\n            <option value=\"\">默认 自动判断</option>\n            <option value=\"4\">强制 IPv4</option>\n            <option value=\"6\">强制 IPv6</option>\n          </select>\n        </div>\n        <div class=\"row\">\n          <label>特殊出口 IP <span class=\"pill\">out_ip</span></label>\n          <input type=\"text\" id=\"out_ip\" placeholder=\"仅出口 IP 与服务器 IP 不一致时填写\">\n        </div>\n        <div class=\"row\">\n          <label>Reality 私钥 <span class=\"pill\">reality_private</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"reality_private\" placeholder=\"留空自动生成（重装保持节点一致），或点右侧按钮\">\n            <button type=\"button\" class=\"mini\" id=\"gen-reality\">生成</button>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <h2>④ Socks5 账号与 IP 白名单 <span class=\"tip\">启用 Socks5 后显示端口与下方账号/白名单</span></h2>\n        <div class=\"row\">\n          <label>启用 Socks5 协议</label>\n          <select id=\"socks5-on\">\n            <option value=\"\">默认 不启用</option>\n            <option value=\"on\">启用</option>\n          </select>\n        </div>\n        <div class=\"row\" id=\"row-socks5pt\" style=\"display:none\">\n          <label>Socks5 端口 <span class=\"pill\">socks5pt</span><span class=\"req\">*</span></label>\n          <input type=\"text\" class=\"port-input\" id=\"socks5pt\" placeholder=\"必填，如 31017，或点 🎲 随机\" inputmode=\"numeric\">\n        </div>\n        <div id=\"socks5-sub\" style=\"display:none\">\n          <div class=\"row\">\n            <label>Socks5 用户名 <span class=\"pill\">socks5_username</span></label>\n            <input type=\"text\" id=\"socks5-username\" placeholder=\"留空自动随机生成\">\n          </div>\n          <div class=\"row\">\n            <label>Socks5 密码 <span class=\"pill\">socks5_password</span></label>\n            <div class=\"ctl\">\n              <input type=\"text\" id=\"socks5-password\" placeholder=\"留空随机生成，或点右侧按钮\">\n              <button type=\"button\" class=\"mini\" id=\"gen-s5pass\">生成</button>\n            </div>\n          </div>\n          <div class=\"row\">\n            <label>IP 白名单开关 <span class=\"pill\">socks5_wl_flag</span></label>\n            <select id=\"socks5-wl\">\n              <option value=\"\">默认 关闭（对所有 IP 开放）</option>\n              <option value=\"on\">开启（仅白名单 IP 可连）</option>\n            </select>\n          </div>\n          <div class=\"row\">\n            <label>白名单 IP 列表 <span class=\"pill\">socks5_ips</span></label>\n            <input type=\"text\" id=\"socks5-ips\" placeholder=\"1.2.3.4,5.6.7.0/24 逗号分隔，支持 CIDR\" disabled>\n          </div>\n          <p class=\"note\">白名单通过 iptables 精确标记实现，卸载/覆盖安装只清理本脚本规则，不影响其他程序。</p>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <h2>⑤ 安装 / 管理动作 <span class=\"pill\">sb.sh 尾部参数</span></h2>\n        <div class=\"row\">\n          <label>执行动作</label>\n          <select id=\"sb-tail\">\n            <option value=\"rep\">rep · 覆盖式安装（默认，可改配置后重装）</option>\n            <option value=\"ins\">ins · 安装（不清理旧配置）</option>\n            <option value=\"del\">del · 卸载（保留二进制）</option>\n            <option value=\"delall\">delall · 全部卸载并清理</option>\n            <option value=\"list\">list · 查看节点</option>\n            <option value=\"list key\">list key · 查看节点 + Reality 私钥</option>\n            <option value=\"ups\">ups · 更新 sing-box 内核</option>\n          </select>\n        </div>\n        <p class=\"note\">选择 del / list / ups 等管理动作时，将只生成不带环境变量的管理命令。</p>\n      </section>\n\n      <section class=\"card\">\n        <h2>⑥ 节点订阅</h2>\n        <div class=\"row\">\n          <label>节点订阅 <span class=\"pill\">subscribe</span></label>\n          <select id=\"subscribe\">\n            <option value=\"\">默认 关闭（不生成订阅）</option>\n            <option value=\"true\">开启（需填写订阅端口）</option>\n          </select>\n        </div>\n        <div class=\"row\" id=\"row-nginx-pt\" style=\"display:none\">\n          <label>Nginx 订阅端口 <span class=\"pill\">nginx_pt</span></label>\n          <input type=\"text\" id=\"nginx_pt\" placeholder=\"默认 8080，不能与 Argo 本地监听端口 同为 8001\" inputmode=\"numeric\" disabled>\n        </div>\n        <p class=\"note\">开启订阅后需填写 Nginx 订阅端口（默认 8080）。</p>\n      </section>\n      </div>\n\n      <section class=\"card span2\">\n        <h2>sb 快捷指令速查 <span class=\"tip\">安装后在服务器执行 sb sc 创建，即可使用</span></h2>\n        <div class=\"cmdlist\" id=\"sb-cmds\"></div>\n      </section>\n    </div>\n  </section>\n\n  <!-- ================= Tab 2 : mtp-new.sh ================= -->\n  <section id=\"tab-mtpnew\" class=\"tabpane\">\n    <div class=\"grid\">\n      <div class=\"col\">\n      <section class=\"card\">\n        <h2>① 安装模式与基础参数</h2>\n        <div class=\"row\">\n          <label>安装模式 <span class=\"pill\">INSTALL_MODE</span></label>\n          <select id=\"mtpn-mode\">\n            <option value=\"go\">Go 版 mtg（轻量）</option>\n            <option value=\"telemt\" selected>Telemt 高性能版（多用户/配额/限速，默认）</option>\n          </select>\n        </div>\n        <div class=\"row\">\n          <label>监听端口 <span class=\"pill\">PORT</span></label>\n          <input type=\"text\" class=\"port-input\" id=\"mtpn-port\" placeholder=\"如 443 / 20301，或点 🎲 随机\" inputmode=\"numeric\">\n        </div>\n        <div class=\"row\">\n          <label>伪装域名 <span class=\"pill\">DOMAIN</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"mtpn-domain\" placeholder=\"留空默认 www.apple.com，或右侧选择\">\n            <select class=\"pick-mtpn-domain\" data-target=\"mtpn-domain\"><option value=\"\" selected>请选择</option></select>\n          </div>\n        </div>\n        <div class=\"row\">\n          <label>监听模式 <span class=\"pill\">IP_MODE</span></label>\n          <select id=\"mtpn-ipmode\">\n            <option value=\"\">默认 v4</option>\n            <option value=\"v4\">v4 · 仅 IPv4</option>\n            <option value=\"v6\">v6 · 仅 IPv6</option>\n            <option value=\"dual\">dual · 双栈监听</option>\n          </select>\n        </div>\n        <div class=\"row\">\n          <label>通信密钥 <span class=\"pill\" id=\"mtpn-secret-label\">SECRET</span></label>\n          <div class=\"ctl\">\n            <input type=\"text\" id=\"mtpn-secret\" placeholder=\"32 位 hex，留空自动生成\">\n            <button type=\"button\" class=\"mini\" id=\"gen-mtpn-secret\">生成</button>\n          </div>\n        </div>\n        <p class=\"note\">自定义 SECRET 后，无论重装多少次，分享链接保持一致（非法值将中止安装）。</p>\n      </section>\n\n      <section class=\"card\" id=\"mtpn-telemt-card\">\n        <h2>③ Telemt 高性能版专属参数</h2>\n        <fieldset class=\"lock-box\" id=\"mtpn-telemt-lock\" disabled>\n          <div class=\"row\">\n            <label>初始管理员用户 <span class=\"pill\">TELEMT_USER</span></label>\n            <input type=\"text\" id=\"mtpn-user\" placeholder=\"默认 admin，不推荐直接用 admin\">\n          </div>\n          <div class=\"row\">\n            <label>月度流量配额 GB <span class=\"pill\">TELEMT_QUOTA</span></label>\n            <input type=\"text\" id=\"mtpn-quota\" placeholder=\"如 100，留空不限流\">\n          </div>\n          <div class=\"row\">\n            <label>到期时间 <span class=\"pill\">TELEMT_EXPIRE</span></label>\n            <input type=\"text\" id=\"mtpn-expire\" placeholder=\"如 2099-12-01 23:59:59，留空永久\">\n          </div>\n          <div class=\"row\">\n            <label>上行限速 MB/s <span class=\"pill\">TELEMT_SPEED_UP</span></label>\n            <input type=\"text\" id=\"mtpn-sup\" placeholder=\"如 1.5，留空不限\">\n          </div>\n          <div class=\"row\">\n            <label>下行限速 MB/s <span class=\"pill\">TELEMT_SPEED_DOWN</span></label>\n            <input type=\"text\" id=\"mtpn-sdn\" placeholder=\"如 5.0，留空同上行\">\n          </div>\n          <div class=\"row\">\n            <label>配额重置日 <span class=\"pill\">TELEMT_RESET_DAY</span></label>\n            <input type=\"text\" id=\"mtpn-reset\" placeholder=\"如 1（每月 1 号，仅设配额后生效）\" inputmode=\"numeric\">\n          </div>\n        </fieldset>\n      </section>\n      </div>\n\n      <div class=\"col\">\n      <section class=\"card\">\n        <h2>② 执行动作</h2>\n        <div class=\"row\">\n          <label>执行动作 <span class=\"pill\">mtp-new.sh 尾部参数</span></label>\n          <select id=\"mtpn-tail\">\n            <option value=\"rep\">rep · 覆盖重装（默认）</option>\n            <option value=\"ins\">ins · 安装（不清理旧配置）</option>\n            <option value=\"del\">del · 全量卸载并清理</option>\n            <option value=\"list\">list · 查看连接信息</option>\n            <option value=\"start\">start · 启动服务</option>\n            <option value=\"stop\">stop · 停止服务</option>\n            <option value=\"restart\">restart · 重启服务</option>\n            <option value=\"usage\">usage · 本月流量统计</option>\n            <option value=\"usage_total\">usage_total · 总流量统计</option>\n          </select>\n        </div>\n        <p class=\"note\">del / list / start / stop / restart / usage 等管理动作只生成裸命令。</p>\n      </section>\n\n      <section class=\"card\" id=\"mg-card\">\n        <h2>④ Telemt 多用户管理命令生成 <span class=\"tip\">需 python3，安装时已自动安装</span></h2>\n        <div class=\"row\">\n          <label class=\"ck\" for=\"mg-ready\"><input type=\"checkbox\" id=\"mg-ready\"> 我已运行上方安装命令，管理员主账号（<span id=\"mg-main-user\">admin</span>）已部署上线</label>\n          <p class=\"note\" id=\"mg-lock-note\">🔒 生成多用户管理命令前，请先在服务器运行上方「Telemt 高性能版」安装命令（rep / ins），确认管理员主账号已部署上线后勾选。</p>\n        </div>\n        <fieldset class=\"lock-box\" id=\"mg-lock\" disabled>\n          <div class=\"row\">\n            <label>管理命令</label>\n            <select id=\"mg-cmd\">\n              <option value=\"adduser\">adduser · 添加用户</option>\n              <option value=\"users\">users · 查看所有用户链接</option>\n              <option value=\"getuser\">getuser · 查询用户配置</option>\n              <option value=\"moduser\">moduser · 修改用户配置</option>\n              <option value=\"deluser\">deluser · 删除用户</option>\n            </select>\n          </div>\n          <div class=\"row\" id=\"row-mg-user\">\n            <label>子账号 <span class=\"pill\">TELEMT_USER</span><span class=\"req\">*</span></label>\n            <input type=\"text\" id=\"mg-user\" placeholder=\"如 vip01\">\n          </div>\n          <div class=\"row\" id=\"row-mg-quota\">\n            <label>配额 GB <span class=\"pill\">TELEMT_QUOTA</span></label>\n            <input type=\"text\" id=\"mg-quota\" placeholder=\"moduser：0 表示解除限制\">\n          </div>\n          <div class=\"row\" id=\"row-mg-expire\">\n            <label>到期时间 <span class=\"pill\">TELEMT_EXPIRE</span></label>\n            <input type=\"text\" id=\"mg-expire\" placeholder=\"如 2099-12-01 23:59:59；moduser：0 表示恢复永久\">\n          </div>\n          <div class=\"row\" id=\"row-mg-port\">\n            <label>专属端口 <span class=\"pill\">TELEMT_DEDICATED_PORT</span></label>\n            <input type=\"text\" id=\"mg-port\" placeholder=\"moduser：0 表示恢复共享端口\" inputmode=\"numeric\">\n          </div>\n          <div class=\"row\" id=\"row-mg-secret\">\n            <label>通信密钥 <span class=\"pill\">TELEMT_SECRET</span></label>\n            <div class=\"ctl\">\n              <input type=\"text\" id=\"mg-secret\" placeholder=\"32 位 hex，留空自动生成\">\n              <button type=\"button\" class=\"mini\" id=\"gen-mg-secret\">生成</button>\n            </div>\n          </div>\n          <div class=\"row\">\n            <label>生成结果</label>\n            <div class=\"ctl\">\n<textarea id=\"mg-out\" rows=\"2\" readonly spellcheck=\"false\" wrap=\"soft\" placeholder=\"选择命令并填写参数后自动生成\"></textarea>\n            <button type=\"button\" class=\"mini\" id=\"mg-copy\">复制</button>\n            </div>\n          </div>\n        </fieldset>\n      </section>\n      </div>\n\n      <section class=\"card span2\">\n        <h2>mtp 管理命令速查 <span class=\"pill\" id=\"mtpn-cmds-flag\">Go 版</span></h2>\n        <div class=\"cmdlist\" id=\"mtpn-cmds\"></div>\n      </section>\n    </div>\n  </section>\n\n  <!-- ================= 输出区 ================= -->\n  <div class=\"grid\">\n    <section class=\"card span2\">\n      <h2>生成的 SSH 一键命令 <span class=\"pill\" id=\"out-script\">sb.sh</span></h2>\n      <div class=\"out-tools\">\n        <label>下载方式\n          <select id=\"dl\">\n            <option value=\"curl\">curl</option>\n            <option value=\"wget\">wget</option>\n          </select>\n        </label>\n        <button id=\"copy\" class=\"primary\" type=\"button\">📋 复制命令</button>\n        <button id=\"reset\" class=\"ghost\" type=\"button\">♻️ 重置表单</button>\n      </div>\n      <textarea id=\"cmd\" readonly spellcheck=\"false\"></textarea>\n      <p class=\"hint\">提示：整段复制粘贴到 SSH 终端回车即可执行（多行 \\ 续行符已处理好）。字符串值已按脚本要求使用英文单引号包裹，含特殊字符的密码也不会被截断。</p>\n    </section>\n  </div>\n\n  <footer>\n    本页面仅为 <a href=\"https://github.com/jyucoeng/singbox-tools\" target=\"_blank\">jyucoeng/singbox-tools</a> 的命令生成辅助界面，脚本功能与版权归原项目所有，仅供学习交流。<br>\n    界面风格参考 <a href=\"https://yonggekkk.github.io/argosbx/\" target=\"_blank\">ArgoSBX 命令生成器</a> · 界面版本 v1.0.0 · 2026-09-05\n  </footer>\n</div>\n\n<script>\n(function () {\n  'use strict';\n  var $id = function (x) { return document.getElementById(x); };\n  var val = function (x) { var e = $id(x); return e ? String(e.value).trim() : ''; };\n\n  var BASE = 'https://raw.githubusercontent.com/jyucoeng/singbox-tools/refs/heads/main/';\n  var URLS = {\n    sb: BASE + 'sb.sh',\n    mtpnew: BASE + 'mtp-new.sh'\n  };\n  var SCRIPT_NAMES = { sb: 'sb.sh', mtpnew: 'mtp-new.sh' };\n\n  /* ---------------- helpers ---------------- */\n  function isNum(v) { return /^-?\\d+(\\.\\d+)?$/.test(v); }\n  // TELEMT_EXPIRE 格式校验：YYYY-MM-DD HH:MM:SS（如 2099-12-01 23:59:59）\n  function validExpire(v) {\n    var m = /^(\\d{4})-(\\d{2})-(\\d{2}) (\\d{2}):(\\d{2}):(\\d{2})$/.exec(v);\n    if (!m) return false;\n    var mo = +m[2], d = +m[3], h = +m[4], mi = +m[5], s = +m[6];\n    if (mo < 1 || mo > 12 || d < 1 || d > new Date(+m[1], mo, 0).getDate()) return false;\n    return h < 24 && mi < 60 && s < 60;\n  }\n  // 到期时间非法时：输入框标红 + 命令框输出错误注释（以 # 开头，误复制到终端也只是注释）\n  var UI_ERRORS = [];\n  function uiError(msg) { UI_ERRORS.push(msg); }\n  function expireErr(id) {\n    $id(id).classList.add('err');\n    uiError('到期时间（TELEMT_EXPIRE）格式错误：应为 YYYY-MM-DD HH:MM:SS，如 2099-12-01 23:59:59');\n    return '# ⚠️ 到期时间（TELEMT_EXPIRE）格式错误：应为 YYYY-MM-DD HH:MM:SS，如 2099-12-01 23:59:59';\n  }\n  // 顶部共享错误横幅（端口冲突、格式错误等），两个 Tab 共用\n  function setGlobalErr(msgs) {\n    var el = $id('err-global');\n    if (!el) return;\n    if (msgs && msgs.length) {\n      el.innerHTML = msgs.map(function (m) { return '⚠️ ' + m; }).join('<br>');\n      el.style.display = '';\n    } else {\n      el.innerHTML = '';\n      el.style.display = 'none';\n    }\n  }\n  function expireClear(id) {\n    var e = $id(id);\n    if (e) e.classList.remove('err');\n  }\n  // sb.sh 要求字符串值用英文单引号包裹；数字裸写\n  function qv(v) {\n    if (v === '') return \"''\";\n    if (isNum(v)) return v;\n    return \"'\" + v.replace(/'/g, \"'\\\\''\") + \"'\";\n  }\n  function wrapCmd(envs, url, tail) {\n    var dl = val('dl') || 'curl';\n    var fetcher = dl === 'curl' ? ('curl -Ls ' + url) : ('wget -qO- ' + url);\n    var s = '';\n    envs.forEach(function (p) {\n      if (p[1] !== '' && p[1] != null) s += p[0] + '=' + p[1] + ' \\\\\\n';\n    });\n    s += 'bash <(' + fetcher + ')' + (tail ? ' ' + tail : '');\n    return s;\n  }\n  function genUuid() {\n    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();\n    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {\n      var r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);\n    });\n  }\n  function genHex32() {\n    var b = new Uint8Array(16);\n    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(b);\n    else for (var i = 0; i < 16; i++) b[i] = Math.random() * 256 | 0;\n    return Array.prototype.map.call(b, function (x) { return ('0' + x.toString(16)).slice(-2); }).join('');\n  }\n  // 与脚本 gen_reality_private() 一致：32 字节随机数的标准 base64\n  function genRealityPrivate() {\n    var b = new Uint8Array(32);\n    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(b);\n    else for (var i = 0; i < 32; i++) b[i] = Math.random() * 256 | 0;\n    var s = '';\n    Array.prototype.forEach.call(b, function (x) { s += String.fromCharCode(x); });\n    return btoa(s);\n  }\n  async function copyText(t) {\n    try { await navigator.clipboard.writeText(t); return true; }\n    catch (e) {\n      var ta = document.createElement('textarea');\n      ta.value = t; ta.style.position = 'fixed'; ta.style.opacity = '0';\n      document.body.appendChild(ta); ta.select();\n      var ok = false;\n      try { ok = document.execCommand('copy'); } catch (_) {}\n      ta.remove(); return ok;\n    }\n  }\n  function flashBtn(btn, ok) {\n    if (!btn) return;\n    var old = btn.getAttribute('data-old') || btn.textContent;\n    btn.setAttribute('data-old', old);\n    btn.textContent = ok ? '✅ 已复制' : '❌ 复制失败';\n    clearTimeout(btn._t);\n    btn._t = setTimeout(function () { btn.textContent = old; }, 1200);\n  }\n\n  /* ---------------- 速查列表渲染 ---------------- */\n  function renderCmdList(id, rows) {\n    var box = $id(id);\n    if (!box) return;\n    box.innerHTML = '';\n    rows.forEach(function (r) {\n      var div = document.createElement('div');\n      div.className = 'crow' + (r[2] === 'hl' ? ' hl' : '');\n      var code = document.createElement('code');\n      code.textContent = r[0];\n      var desc = document.createElement('span');\n      desc.className = 'cdesc';\n      desc.textContent = r[1];\n      var btn = document.createElement('button');\n      btn.className = 'mini';\n      btn.type = 'button';\n      btn.textContent = '复制';\n      btn.addEventListener('click', async function () {\n        flashBtn(btn, await copyText(r[0]));\n      });\n      div.appendChild(code); div.appendChild(desc); div.appendChild(btn);\n      box.appendChild(div);\n    });\n  }\n\n  var SB_CMDS = [\n    ['sb', '打开主菜单'],\n    ['sb ins', '安装节点'],\n    ['sb rep', '覆盖式安装/重置'],\n    ['sb list', '查看节点信息'],\n    ['sb list key', '查看节点 + vless Reality 私钥'],\n    ['sb res', '重启 sing-box 和 cloudflared'],\n    ['sb rt', '分流管理'],\n    ['sb node', '节点配置修改（端口/订阅/SNI/Argo）'],\n    ['sb sub', '订阅管理'],\n    ['sb del', '卸载（保留二进制）'],\n    ['sb delall', '卸载全部并清理'],\n    ['sb ups', '更新 sing-box 内核'],\n    ['sb sc', '创建/刷新本快捷命令'],\n    ['sb sc_off', '删除本快捷命令'],\n    ['sb autostart', '开启开机自启'],\n    ['sb autostart_off', '关闭开机自启'],\n    ['sb nginx_start', '启动 Nginx'],\n    ['sb nginx_stop', '停止 Nginx'],\n    ['sb nginx_restart', '重启 Nginx'],\n    ['sb nginx_status', '查看 Nginx 状态'],\n    ['sb logs', '打开日志菜单'],\n    ['sb log_sb 100', '查看 Sing-box 运行日志（最近100行）'],\n    ['sb log_argo 100', '查看 Argo 隧道日志（最近100行）'],\n    ['sb log_ins 100', '查看脚本安装日志（最近100行）'],\n    ['sb log_stop', '查看服务停止原因日志']\n  ];\n\n  function mtpnLine(args, desc) {\n    return ['bash <(curl -Ls ' + URLS.mtpnew + ')' + (args ? ' ' + args : ''), desc];\n  }\n  // 带环境变量前缀的示例命令（envStr 用双引号包裹，内部可写单引号）\n  function mtpnEnv(envStr, args, desc) {\n    return [envStr + ' bash <(curl -Ls ' + URLS.mtpnew + ')' + (args ? ' ' + args : ''), desc];\n  }\n  var MTPN_CMDS_COMMON = [\n    mtpnLine('ins', '安装（不清理旧配置）'),\n    mtpnLine('rep', '覆盖重装（保留脚本本体与 mtp 命令）'),\n    mtpnLine('del', '全量卸载并清理'),\n    mtpnLine('start', '启动服务'),\n    mtpnLine('stop', '停止服务'),\n    mtpnLine('restart', '重启服务'),\n    mtpnLine('list', '查看已安装服务连接信息')\n  ];\n  var MTPN_CMDS_TELEMT = [\n    ['bash <(curl -Ls ' + URLS.mtpnew + ') users', '查看 Telemt 用户列表及专属分享链接', 'hl'],\n    mtpnEnv(\"TELEMT_USER='vip01' TELEMT_QUOTA=100 TELEMT_EXPIRE='2099-12-01 23:59:59' TELEMT_DEDICATED_PORT=20301 TELEMT_SPEED_UP='1.5' TELEMT_SPEED_DOWN='5.0'\", 'adduser', '添加 Telemt 用户（配额/到期/专属端口/上下行限速；通信密钥留空自动生成）'),\n    mtpnEnv(\"TELEMT_USER='vip01'\", 'getuser', '查询指定用户当前配置'),\n    mtpnEnv(\"TELEMT_USER='vip01' TELEMT_QUOTA=200 TELEMT_EXPIRE='2027-06-30 23:59:59'\", 'moduser', '修改用户（示例改配额+到期；支持 密钥/端口/配额/到期/限速，填 0 解除）'),\n    mtpnEnv(\"TELEMT_USER='vip01'\", 'deluser', '删除指定用户'),\n    mtpnLine('force_reset', '手动立即重置全部活跃用户的月度配额（不需要任何参数，无视配额重置日）'),\n    mtpnLine('usage', '本月流量使用统计（含耗尽时间）'),\n    mtpnLine('usage_total', '总流量统计（历史累计排名）'),\n    mtpnLine('tg_report', '立即推送本月统计到 Telegram')\n  ];\n  // mtp 管理命令速查按 INSTALL_MODE 动态渲染：Go 版只显示通用命令，Telemt 版才追加用户管理类命令\n  function renderMtpnCmds() {\n    var mode = val('mtpn-mode');\n    var isTelemt = mode === 'telemt';\n    var flag = $id('mtpn-cmds-flag');\n    if (flag) flag.textContent = isTelemt ? 'Telemt 高性能版' : 'Go 版';\n    renderCmdList('mtpn-cmds', MTPN_CMDS_COMMON.concat(isTelemt ? MTPN_CMDS_TELEMT : []));\n  }\n\n  /* ---------------- 命令生成 ---------------- */\n  var SB_MGMT_TAILS = ['del', 'delall', 'list', 'list key', 'ups'];\n  var MTPN_MGMT_TAILS = ['del', 'list', 'start', 'stop', 'restart', 'usage', 'usage_total'];\n\n  function numEnv(k, id, envs) {\n    var v = val(id);\n    if (v) envs.push([k, isNum(v) ? v : qv(v)]);\n  }\n  function strEnv(k, id, envs) {\n    var v = val(id);\n    if (v) envs.push([k, qv(v)]);\n  }\n\n  function buildSb() {\n    var tail = val('sb-tail') || 'rep';\n    if (SB_MGMT_TAILS.indexOf(tail) >= 0) return wrapCmd([], URLS.sb, tail);\n    var envs = [];\n    strEnv('uuid', 'uuid', envs);\n    numEnv('ippz', 'ippz', envs);\n    strEnv('out_ip', 'out_ip', envs);\n    strEnv('hy_sni', 'hy_sni', envs);\n    strEnv('vl_sni', 'vl_sni', envs);\n    strEnv('tu_sni', 'tu_sni', envs);\n    strEnv('any_sni', 'any_sni', envs);\n    // 直连协议端口\n    ['hypt', 'vlrt', 'tupt', 'anypt'].forEach(function (k) { numEnv(k, k, envs); });\n    // Argo 三选一\n    var argo = val('argo');\n    if (argo) {\n      numEnv(argo, 'argo-port', envs);\n      envs.push(['argo', \"'\" + argo + \"'\"]);\n    }\n    // Socks5\n    numEnv('socks5pt', 'socks5pt', envs);\n    strEnv('socks5_username', 'socks5-username', envs);\n    strEnv('socks5_password', 'socks5-password', envs);\n    if (val('socks5-wl') === 'on') {\n      envs.push(['socks5_wl_flag', 'true']);\n      strEnv('socks5_ips', 'socks5-ips', envs);\n    }\n    // Argo 隧道 / CDN / 订阅\n    strEnv('agn', 'agn', envs);\n    strEnv('agk', 'agk', envs);\n    strEnv('cdn_host', 'cdn_host', envs);\n    numEnv('cdn_pt', 'cdn_pt', envs);\n    numEnv('argo_pt', 'argo_pt', envs);\n    if (val('subscribe') === 'true') {\n      envs.push(['subscribe', 'true']);\n      numEnv('nginx_pt', 'nginx_pt', envs);\n    }\n    strEnv('reality_private', 'reality_private', envs);\n    strEnv('name', 'name', envs);\n    return wrapCmd(envs, URLS.sb, tail);\n  }\n\n  function buildMtpNew() {\n    expireClear('mtpn-expire');\n    var mode = val('mtpn-mode');\n    var tail = val('mtpn-tail') || 'rep';\n    if (MTPN_MGMT_TAILS.indexOf(tail) >= 0) return wrapCmd([], URLS.mtpnew, tail);\n    var envs = [];\n    numEnv('PORT', 'mtpn-port', envs);\n    strEnv('DOMAIN', 'mtpn-domain', envs);\n    strEnv('IP_MODE', 'mtpn-ipmode', envs);\n    if (mode === 'go') {\n      strEnv('SECRET', 'mtpn-secret', envs);\n    } else {\n      if (val('mtpn-expire') && !validExpire(val('mtpn-expire'))) return expireErr('mtpn-expire');\n      envs.push(['INSTALL_MODE', \"'telemt'\"]);\n      strEnv('TELEMT_USER', 'mtpn-user', envs);\n      strEnv('TELEMT_SECRET', 'mtpn-secret', envs);\n      strEnv('TELEMT_QUOTA', 'mtpn-quota', envs);\n      strEnv('TELEMT_EXPIRE', 'mtpn-expire', envs);\n      strEnv('TELEMT_SPEED_UP', 'mtpn-sup', envs);\n      strEnv('TELEMT_SPEED_DOWN', 'mtpn-sdn', envs);\n      strEnv('TELEMT_RESET_DAY', 'mtpn-reset', envs);\n    }\n    return wrapCmd(envs, URLS.mtpnew, tail);\n  }\n\n  /* ---------------- Telemt 用户管理 ---------------- */\n  function buildMg() {\n    // ④ 勾选文案里的主账号名跟随 ② TELEMT_USER 输入实时变化\n    var mu = $id('mg-main-user');\n    if (mu) mu.textContent = val('mtpn-user') || 'admin';\n    expireClear('mg-expire');\n    var mode = val('mtpn-mode');\n    var ready = $id('mg-ready') && $id('mg-ready').checked;\n    if (mode !== 'telemt' || !ready) return '';\n    var c = val('mg-cmd') || 'adduser';\n    var fetcher = 'curl -Ls ' + URLS.mtpnew;\n    var user = val('mg-user');\n    if (c === 'users') return 'bash <(curl -Ls ' + URLS.mtpnew + ') users';\n    if (!user) return '';\n    var envs = [['TELEMT_USER', qv(user)]];\n    if (c === 'adduser' || c === 'moduser') {\n      var mgExp = val('mg-expire');\n      if (mgExp && mgExp !== '0' && !validExpire(mgExp)) return expireErr('mg-expire');\n      strEnv2('TELEMT_QUOTA', 'mg-quota', envs);\n      strEnv2('TELEMT_EXPIRE', 'mg-expire', envs);\n      strEnv2('TELEMT_SECRET', 'mg-secret', envs);\n      numEnv('TELEMT_DEDICATED_PORT', 'mg-port', envs);\n    }\n    var s = '';\n    envs.forEach(function (p) { if (p[1] !== '') s += p[0] + '=' + p[1] + ' \\\\\\n'; });\n    return s + 'bash <(curl -Ls ' + URLS.mtpnew + ') ' + c;\n  }\n  function strEnv2(k, id, envs) { var v = val(id); if (v) envs.push([k, qv(v)]); }\n\n  /* ---------------- 状态联动 ---------------- */\n  function syncArgoPort() {\n    var argo = val('argo');\n    var on = !!argo;\n    var row = $id('row-argo-port');\n    var card = $id('argo-tunnel-card');\n    if (row) row.style.display = on ? '' : 'none';\n    if (card) {\n      card.style.display = on ? '' : 'none';\n      if (!on) {\n        // 未启用 Argo：恢复默认值\n        $id('argo-port').value = '';\n        $id('agn').value = '';\n        $id('agk').value = '';\n        $id('cdn_host').value = '';\n        $id('cdn_pt').value = '';\n        $id('argo_pt').value = '';\n        $id('tunnel-type').value = 'fixed';\n      }\n    }\n    $id('argo-port').disabled = !on;\n    $id('argo-port-pill').textContent = argo || 'vmpt';\n    $id('argo-port').placeholder = on ? ('如 41003（' + argo + ' 的本地端口）') : '先选择 Argo 协议';\n    syncTunnelType();\n    renumberCards();\n  }\n  function syncNginx() {\n    var on = val('subscribe') === 'true';\n    $id('row-nginx-pt').style.display = on ? '' : 'none';\n    $id('nginx_pt').disabled = !on;\n    if (!on) $id('nginx_pt').value = '';\n  }\n  function syncWl() {\n    $id('socks5-ips').disabled = val('socks5-wl') !== 'on';\n  }\n  // 端口冲突检测：仅 Singbox 页启用（mtp 页不做端口冲突检测），相同值端口同时标红发光并给出原因\n  var PORT_SB = ['hypt', 'vlrt', 'tupt', 'anypt', 'argo-port', 'socks5pt', 'argo_pt', 'nginx_pt', 'cdn_pt'];\n  var PORT_LABELS = {\n    hypt: 'Hysteria2 端口', vlrt: 'Vless-Reality 端口', tupt: 'Tuic 端口', anypt: 'AnyTLS 端口',\n    'argo-port': 'Argo 本地端口', socks5pt: 'Socks5 端口', argo_pt: 'Argo 本地监听端口',\n    nginx_pt: 'Nginx 订阅端口', cdn_pt: 'CF 对外端口'\n  };\n  function checkPortConflict() {\n    if (currentTab() !== 'sb') return [];\n    var ids = PORT_SB;\n    var groups = {};\n    var vals = {};\n    ids.forEach(function (id) {\n      var el = $id(id);\n      var v = el ? String(el.value).trim() : '';\n      vals[id] = v;\n      if (v) (groups[v] = groups[v] || []).push(id);\n    });\n    ids.forEach(function (id) {\n      var el = $id(id);\n      if (!el) return;\n      var v = vals[id];\n      var conflicted = v && groups[v] && groups[v].length > 1;\n      if (conflicted) {\n        el.classList.add('err');\n        var others = groups[v].filter(function (x) { return x !== id; })\n                             .map(function (x) { return PORT_LABELS[x] || x; }).join('、');\n        el.setAttribute('title', '端口冲突：' + (PORT_LABELS[id] || id) + ' 与 ' + others + ' 使用了同一个端口 ' + v);\n      } else {\n        el.classList.remove('err');\n        el.removeAttribute('title');\n      }\n    });\n    var msgs = [];\n    Object.keys(groups).forEach(function (v) {\n      if (groups[v].length > 1) {\n        msgs.push('端口 ' + v + ' 冲突：' + groups[v].map(function (x) { return PORT_LABELS[x] || x; }).join('、') + ' 使用了同一个端口');\n      }\n    });\n    return msgs;\n  }\n  function checkSocks5Required() {\n    if (currentTab() !== 'sb') return [];\n    var el = $id('socks5pt');\n    if (!el) return [];\n    if (val('socks5-on') === 'on') {\n      if (!val('socks5pt')) {\n        el.classList.add('err');\n        el.setAttribute('title', '已启用 Socks5：端口必填（可点 🎲 随机生成）');\n        return ['已启用 Socks5 但端口为空：命令将缺少 socks5pt，Socks5 不会启用（请填写端口或点 🎲）'];\n      }\n      return [];\n    }\n    el.classList.remove('err');\n    el.removeAttribute('title');\n    return [];\n  }\n  // Socks5 账号/白名单区：由“启用 Socks5 协议”开关控制\n  function syncSocks5() {\n    // 由“启用 Socks5 协议”开关统一控制：启用则显示端口与账号/白名单，不启用则整体隐藏并清空\n    var enabled = val('socks5-on') === 'on';\n    var portRow = $id('row-socks5pt');\n    var sub = $id('socks5-sub');\n    if (portRow) portRow.style.display = enabled ? '' : 'none';\n    if (sub) sub.style.display = enabled ? '' : 'none';\n    if (!enabled) {\n      $id('socks5pt').value = '';\n      $id('socks5-username').value = '';\n      $id('socks5-password').value = '';\n      $id('socks5-wl').value = '';\n      $id('socks5-ips').value = '';\n    }\n    syncWl();\n  }\n  // 直连协议 SNI：仅当对应端口填了值才显示；端口清空时同步清空对应 SNI\n  function syncSniByPort() {\n    var pairs = [['hypt', 'row-hy-sni', 'hy_sni'], ['vlrt', 'row-vl-sni', 'vl_sni'], ['tupt', 'row-tu-sni', 'tu_sni'], ['anypt', 'row-any-sni', 'any_sni']];\n    pairs.forEach(function (p) {\n      var on = !!val(p[0]);\n      $id(p[1]).style.display = on ? '' : 'none';\n      if (!on) $id(p[2]).value = '';\n    });\n  }\n  function syncTunnelType() {\n    var fixed = val('tunnel-type') === 'fixed';\n    $id('row-agn').style.display = fixed ? '' : 'none';\n    $id('row-agk').style.display = fixed ? '' : 'none';\n    $id('agn').disabled = !fixed;\n    $id('agk').disabled = !fixed;\n    if (!fixed) { $id('agn').value = ''; $id('agk').value = ''; }\n    var n = $id('tunnel-note');\n    if (n) n.innerHTML = fixed\n      ? '固定隧道：请填写上方「Argo 固定隧道域名」与「Argo 隧道 Token」；自有 CF Tunnel 可在 <a href=\"https://fscarmen.cloudflare.now.cc\" target=\"_blank\">fscarmen CF Json 生成网</a> 获取 JSON Token（仅选了 Argo 协议才需要）。'\n      : '临时隧道：Cloudflare 自动分配随机域名（如 xxx.trycloudflare.com），无需配置域名/Token，服务重启域名会变，适合临时测试。<br><span class=\"warn-org\">⚠️ 临时隧道在 VPS 重启后，订阅地址和 Argo 节点会发生改变。</span>';\n  }\n  function syncMtpnMode() {\n    var mode = val('mtpn-mode');\n    var isTelemt = mode === 'telemt';\n    $id('mtpn-secret-label').textContent = isTelemt ? 'TELEMT_SECRET' : 'SECRET';\n    // ② Telemt 专属参数：仅 Telemt 模式显示\n    var tCard = $id('mtpn-telemt-card');\n    var tLock = $id('mtpn-telemt-lock');\n    if (tCard) tCard.style.display = isTelemt ? '' : 'none';\n    if (tLock) tLock.disabled = false;\n    syncMgLock();\n    renderMtpnCmds();\n  }\n  // ④ Telemt 多用户管理：选 Go 版时整体隐藏；选 Telemt 版时需勾选确认主账号后解锁\n  function syncMgLock() {\n    var card = $id('mg-card');\n    if (!card) return;\n    var mode = val('mtpn-mode');\n    if (mode !== 'telemt') {\n      var rb = $id('mg-ready');\n      if (rb) rb.checked = false;\n      card.style.display = 'none';\n      return;\n    }\n    card.style.display = '';\n    var ready = $id('mg-ready') && $id('mg-ready').checked;\n    var lock = $id('mg-lock');\n    if (lock) lock.disabled = !ready;\n    card.classList.toggle('locked', !ready);\n    var note = $id('mg-lock-note');\n    if (note) note.textContent = ready\n      ? '✅ 管理员主账号已确认部署，可生成 Telemt 多用户管理命令。'\n      : '🔒 生成多用户管理命令前，请先在服务器运行上方「Telemt 高性能版」安装命令（rep / ins），确认管理员主账号已部署上线后勾选。';\n    var out = $id('mg-out');\n    if (ready) {\n      out.placeholder = '选择命令并填写参数后自动生成';\n    } else {\n      out.placeholder = '🔒 未解锁：需先确认完成主账号安装';\n      out.value = '';\n    }\n  }\n\n  // ④ 参数行按选中的管理命令显示（对齐 mtp-new.sh 各命令读取的字段）：\n  //   users 全隐藏；getuser/deluser 仅用户名；adduser/moduser 全部显示\n  function syncMgFields() {\n    var c = val('mg-cmd') || 'adduser';\n    var showUser = c !== 'users';\n    var showAll = c === 'adduser' || c === 'moduser';\n    function vis(id, on) { var el = $id(id); if (el) el.style.display = on ? '' : 'none'; }\n    vis('row-mg-user', showUser);\n    vis('row-mg-quota', showAll);\n    vis('row-mg-expire', showAll);\n    vis('row-mg-port', showAll);\n    vis('row-mg-secret', showAll);\n    // 提示文案按命令切换（对齐 mtp-new.sh 各命令的留空默认值）\n    var isMod = c === 'moduser';\n    var isAdd = c === 'adduser';\n    var u = $id('mg-user'), q = $id('mg-quota'), e = $id('mg-expire'), p = $id('mg-port'), s = $id('mg-secret');\n    if (u) u.placeholder = isAdd ? '如 vip01（必填）' : '如 vip01';\n    if (q) q.placeholder = isAdd ? '如 100，留空不限流' : (isMod ? '0 解除限制 / 如 100' : '');\n    if (e) e.placeholder = isAdd ? '如 2099-12-01 23:59:59，留空永久' : (isMod ? '0 恢复永久 / 2099-12-01 23:59:59' : '');\n    if (p) p.placeholder = isAdd ? '留空用共享端口，或填如 20301' : (isMod ? '0 恢复共享端口 / 如 20301' : '');\n    if (s) s.placeholder = isAdd ? '32 位 hex，留空自动生成' : (isMod ? '留空表示不修改，或填 32 位 hex' : '');\n  }\n\n  /* ---------------- 卡片动态编号（避免显隐导致编号断档） ---------------- */\n  var CARD_NUMS = ['①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑨', '⑩'];\n  // 初始化：把卡片 h2 开头的编号包进 .card-num，便于动态重编号\n  function initCardNums() {\n    document.querySelectorAll('.col > .card > h2').forEach(function (h2) {\n      if (h2.getAttribute('data-num')) return;\n      var html = h2.innerHTML;\n      var m = /^[①-⑩]\\s*/.exec(html);\n      if (m) {\n        h2.innerHTML = '<span class=\"card-num\">' + m[0].trim() + '</span> ' + html.slice(m[0].length);\n        h2.setAttribute('data-num', '1');\n      }\n    });\n  }\n  // 按当前激活 Tab 内所有可见卡片的 DOM 顺序全局唯一编号（隐藏跳过，编号始终连续、不跨列重复）\n  function renumberCards() {\n    var pane = document.querySelector('.tabpane.active');\n    if (!pane) return;\n    var i = 0;\n    pane.querySelectorAll('.card h2 .card-num').forEach(function (num) {\n      var card = num.closest('.card');\n      if (!card || card.style.display === 'none') return;\n      num.textContent = CARD_NUMS[i] || (i + 1);\n      i++;\n    });\n  }\n\n  /* ---------------- 当前 Tab 与总刷新 ---------------- */\n  function currentTab() {\n    var b = document.querySelector('.tab.active');\n    return b ? b.getAttribute('data-tab') : 'sb';\n  }\n  function autoGrow(el) {\n    if (!el) return;\n    el.style.height = 'auto';\n    el.style.height = el.scrollHeight + 'px';\n  }\n  function regen() {\n    UI_ERRORS = [];\n    syncMgFields();\n    syncSniByPort();\n    syncSocks5();\n    var conflicts = checkPortConflict();\n    var s5req = checkSocks5Required();\n    syncTunnelType();\n    var warn = '';\n    if (conflicts.length) warn = conflicts.map(function (c) { return '# ⚠️ ' + c; }).join('\\n') + '\\n';\n    if (s5req.length) warn += s5req.map(function (c) { return '# ⚠️ ' + c; }).join('\\n') + '\\n';\n    $id('cmd').value = warn + (currentTab() === 'sb' ? buildSb() : buildMtpNew());\n    var mo = $id('mg-out');\n    mo.value = warn + buildMg();\n    autoGrow(mo);\n    if (conflicts.length) uiError('存在端口冲突：' + conflicts.join('；'));\n    if (s5req.length) uiError(s5req.join('；'));\n    setGlobalErr(UI_ERRORS);\n    renumberCards();\n  }\n\n  /* ---------------- 事件绑定 ---------------- */\n  document.querySelectorAll('.tab').forEach(function (b) {\n    b.addEventListener('click', function () {\n      document.querySelectorAll('.tab').forEach(function (x) { x.classList.toggle('active', x === b); });\n      var t = b.getAttribute('data-tab');\n      document.querySelectorAll('.tabpane').forEach(function (p) {\n        p.classList.toggle('active', p.id === 'tab-' + t);\n      });\n      $id('out-script').textContent = SCRIPT_NAMES[t];\n      regen();\n      // 切换 Tab 时暂时清空共享错误横幅，交互后重新计算\n      UI_ERRORS = [];\n      setGlobalErr([]);\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    });\n  });\n\n  document.addEventListener('input', function (e) {\n    var t = e.target;\n    if (t && t.id && /^(hy_sni|vl_sni|tu_sni|any_sni)$/.test(t.id)) {\n      var s = document.querySelector('select.sni-pick[data-target=\"' + t.id + '\"]');\n      if (s) s.selectedIndex = 0;\n    }\n    regen();\n  });\n  document.addEventListener('change', function () { syncArgoPort(); syncNginx(); syncWl(); syncMtpnMode(); regen(); });\n\n  // 纯字母数字密码（不含易混淆的 0/O/1/l/I），与脚本自动生成规则一致，无转义隐患\n  function genPassword() {\n    var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';\n    var arr = new Uint8Array(16);\n    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(arr);\n    else for (var i = 0; i < 16; i++) arr[i] = Math.random() * 256 | 0;\n    return Array.prototype.map.call(arr, function (x) { return chars[x % chars.length]; }).join('');\n  }\n  $id('gen-uuid').addEventListener('click', function () { $id('uuid').value = genUuid(); regen(); });\n  $id('gen-s5pass').addEventListener('click', function () { $id('socks5-password').value = genPassword(); regen(); });\n  $id('gen-reality').addEventListener('click', function () { $id('reality_private').value = genRealityPrivate(); regen(); });\n  $id('gen-mtpn-secret').addEventListener('click', function () { $id('mtpn-secret').value = genHex32(); regen(); });\n  $id('gen-mg-secret').addEventListener('click', function () { $id('mg-secret').value = genHex32(); regen(); });\n\n  $id('mg-copy').addEventListener('click', async function () {\n    var t = $id('mg-out').value;\n    if (t) flashBtn($id('mg-copy'), await copyText(t));\n  });\n\n  $id('copy').addEventListener('click', async function () {\n    flashBtn($id('copy'), await copyText($id('cmd').value));\n  });\n  $id('reset').addEventListener('click', function () { location.reload(); });\n\n  /* ---------------- 主题 ---------------- */\n  var themeBtn = $id('theme-btn');\n  function applyTheme(t) {\n    document.body.classList.toggle('light-mode', t === 'light');\n    themeBtn.textContent = t === 'light' ? '🌙' : '☀️';\n    try { localStorage.setItem('sbti-theme', t); } catch (e) {}\n  }\n  themeBtn.addEventListener('click', function () {\n    applyTheme(document.body.classList.contains('light-mode') ? 'dark' : 'light');\n  });\n  var savedTheme = 'dark';\n  try { savedTheme = localStorage.getItem('sbti-theme') || 'dark'; } catch (e) {}\n  applyTheme(savedTheme);\n\n  /* ---------------- 初始化 ---------------- */\n  // 给所有端口输入框追加 🎲 随机端口按钮\n  function randPort() { return 10000 + Math.floor(Math.random() * 55536); }\n  document.querySelectorAll('input.port-input').forEach(function (inp) {\n    var wrap = document.createElement('div');\n    wrap.className = 'ctl';\n    inp.parentNode.insertBefore(wrap, inp);\n    wrap.appendChild(inp);\n    var btn = document.createElement('button');\n    btn.type = 'button';\n    btn.className = 'mini';\n    btn.textContent = '🎲';\n    btn.title = '填入随机端口（10000-65535）';\n    btn.addEventListener('click', function () {\n      if (inp.disabled) inp.disabled = false;\n      if (inp.id === 'argo-port' && !val('argo')) {\n        var sel = $id('argo');\n        sel.value = 'vmpt';\n        sel.dispatchEvent(new Event('change', { bubbles: true }));\n      }\n      inp.value = randPort();\n      regen();\n    });\n    wrap.appendChild(btn);\n  });\n\n  // SNI 伪装域名候选列表（下拉可反复选择，输入框仍可手输）\n  var SNI_LIST = ['www.ua.edu', 'www.yahoo.com', 'www.apple.com', 'dl.google.com'];\n  document.querySelectorAll('select.sni-pick').forEach(function (sel) {\n    SNI_LIST.forEach(function (d) {\n      var o = document.createElement('option');\n      o.value = d;\n      o.textContent = d;\n      sel.appendChild(o);\n    });\n    sel.addEventListener('change', function () {\n      if (!sel.value) return;\n      $id(sel.getAttribute('data-target')).value = sel.value;\n      sel.selectedIndex = 0;\n      regen();\n    });\n  });\n\n  // CF 优选域名候选（前两项为推荐值；cdn_host 留空时脚本默认 saas.sin.fan）\n  var CDN_LIST = ['saas.sin.fan', 'cdn.dada.nyc.mn', 'cdns.doon.eu.org', 'cf.090227.xyz', 'cf.877774.xyz', 'cf.008500.xyz', 'www.shopify.com', 'mfa.gov.ua', 'cf.zhetengsha.eu.org', 'store.ubi.com', 'sub.danfeng.eu.org', 'cf.877771.xyz', 'cf.130519.xyz', 'cf.tencentapp.cn', 'cf.cloudflare.182682.xyz', 'bestcf.030101.xyz', 'cdn.2020111.xyz', 'cf.0sm.com', 'cf.900501.xyz', 'cfip.1323123.xyz', 'cfip.cfcdn.vip', 'cfip.xxxxxxxx.tk', 'cloudflare.182682.xyz', 'cloudflare-dl.byoip.top', 'cloudflare-ip.mofashi.ltd', 'fn.130519.xyz', 'freeyx.cloudflare88.eu.org'];\n  var cdnSel = document.querySelector('select.pick-cdn[data-target=\"cdn_host\"]');\n  CDN_LIST.forEach(function (d) {\n    var o = document.createElement('option');\n    o.value = d;\n    o.textContent = d;\n    cdnSel.appendChild(o);\n  });\n  cdnSel.addEventListener('change', function () {\n    if (!cdnSel.value) return;\n    $id('cdn_host').value = cdnSel.value;\n    cdnSel.selectedIndex = 0;\n    regen();\n  });\n\n  // MTProxy 伪装域名候选（下拉可反复选择，输入框仍可手输）\n  var DOMAIN_LIST = ['www.apple.com', 'www.microsoft.com', 'www.amazon.com', 'www.bing.com', 'www.mozilla.org', 'www.wikipedia.org'];\n  var mtpnDomainSel = document.querySelector('select.pick-mtpn-domain[data-target=\"mtpn-domain\"]');\n  DOMAIN_LIST.forEach(function (d) {\n    var o = document.createElement('option');\n    o.value = d;\n    o.textContent = d;\n    mtpnDomainSel.appendChild(o);\n  });\n  mtpnDomainSel.addEventListener('change', function () {\n    if (!mtpnDomainSel.value) return;\n    $id('mtpn-domain').value = mtpnDomainSel.value;\n    mtpnDomainSel.selectedIndex = 0;\n    regen();\n  });\n\n  renderCmdList('sb-cmds', SB_CMDS);\n  renderMtpnCmds();\n  // MTProxy 新版：打开时端口 / 通信密钥 默认给随机值\n  if (!$id('mtpn-port').value) $id('mtpn-port').value = String(randPort());\n  if (!$id('mtpn-secret').value) $id('mtpn-secret').value = genHex32();\n  initCardNums();\n  syncArgoPort(); syncNginx(); syncWl(); syncMtpnMode();\n  regen();\n})();\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== '/') {
      return new Response('Not Found', { status: 404 });
    }
    return new Response(HTML, {
      headers: {
        'content-type': 'text/html;charset=UTF-8',
        'cache-control': 'no-store',
      },
    });
  },
};
